{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel0 \b \fs36 ChronoWarp\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Creative Half-Time and Varispeed Engine with continuous ring-buffer time stretching, smooth windowing, dual bandpass filtering, and shimmer pitch layering.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel2 \b \fs28 Features\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Three speed modes: 1.5x (-5 semitones), 2x Half-Time (-1 octave), 4x Quarter-Time (-2 octaves)\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Synchronized loop lengths from 1/16 up to 8 Bars\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Continuous Smooth contour control for percussion/FX vs sustain/swell\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Dual bandpass filtering (Low Cut & High Cut) with Band Solo mode\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Tempo-synced Fade In and Fade Out envelopes to eliminate clicks\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Forward and Reverse playback directions\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Upper-octave shimmer layer with blend control\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Scalable HiDPI text zoom (100% - 140%)\sa180\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel0 \b \fs36 Opto2A\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Optical Tube Compressor with program-dependent T4 photocell attenuation and tube output stage modeling.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel2 \b \fs28 Features\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Authentic T4 optical attenuator modeling with two-stage release memory\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Switchable Compress and Limit modes\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab HF Emphasis (R37) sidechain filter control for frequency-dependent compression\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Classic vs Fast opto cell response modes\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab High-resolution scrolling Gain Reduction trace and illuminated VU meter\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Scalable HiDPI text zoom\sa180\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel2 \b \fs28 Credits\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Core DSP algorithms by JClones (https://github.com/JClones/JSFXClones), licensed under MIT.\sa180\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel0 \b \fs36 OverTop\par}
{\pard \ql \f0 \sa180 \li0 \fi0 3-Band Upward and Downward Multiband Dynamics Processor (OTT style) for aggressive presence, punch, and detail leveling.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel2 \b \fs28 Features\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab 3-band split crossover (88 Hz and 2.5 kHz) with independent upward and downward compression engines\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Interactive threshold bar editing: drag horizontally to shift thresholds per band\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Per-band bypass switches and dedicated band output gain trims\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Global Depth, Time scaling, and In/Out gain controls\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Dedicated Upward % and Downward % intensity knobs\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Modern animated vector UI with real-time level meters and gain reduction traces\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Scalable HiDPI text zoom (100% - 140%)\sa180\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel0 \b \fs36 SpectralCarver\par}
{\pard \ql \f0 \sa180 \li0 \fi0 32-Band Dynamic Spectral Ducker using Cytomic SVF filters.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel2 \b \fs28 Features\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab 32-band Cytomic SVF dynamic spectral ducking\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab High-contrast visualizer with smooth animated controls and hover halos\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Stereo (L/R) and Mid/Side (M/S) processing modes\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Low-cut and high-cut sidechain filtering with interactive spectrum display\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Sidechain audition mode, freeze function, and scalable UI text zoom\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Safe ceiling and NaN/Inf protection\sa180\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel2 \b \fs28 Routing\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Route sidechain control audio to Channels 3/4.\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
